 * Thẻ từ vựng IELTS hoàn chỉnh.
 * - 4 Chủ đề Cambridge 16-19 (100+ từ mỗi chủ đề)
 * - 3 Bộ thẻ kỹ năng: Writing Task 2 (40 từ), Speaking Idioms (35 từ), Listening Signposts (35 từ)
 * Tổng cộng: 513 từ vựng phong phú.
 */
data class VocabularyWord(
    val id: String,
    val topicId: String,
    val word: String,
    val phonetic: String,
    val pos: String,
    val band: Double,
    val meaningVi: String,
    val definition: String,
    val example: String,
    val exampleVi: String,
    val collocations: String,
    val synonyms: String,
    val antonyms: String
) {
    val isAdvanced: Boolean get() = band >= 7.0
}

data class VocabularyTopic(
    val id: String,
    val title: String,
    val titleVi: String,
    val iconRes: Int,
    val accentColor: String,
    val tileColor: String
)

